#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# VHigh investigation bench session (TWIST simulation/vhigh_overvoltage).
# Bench tests L2-OV-01, L2-OV-02 and L2-STP-01, each compared with the model
# prediction of the same setup (cases D-L2P-01..06). Resume an interrupted
# session with: SESSION=<results/bench_... folder> ./bench_wizard.sh

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
RESULTS="$(cd "$HERE/../results" && pwd)"
PY="${PY:-$HOME/code/Core2/.venv/bin/python}"
PIO="${PIO:-$HOME/.platformio/penv/bin/pio}"
CTL="$HERE/bench_ctl.py"

ctl()  { "$PY" "$CTL" --port "$TS_PORT" "$@"; }
idle() { ctl set Converter/Mode 0 >/dev/null 2>&1 || warn "could not write Mode 0: switch the supplies off"; }
run()  { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }

run_wizard() {

TOTAL_STAGES=12

SESSION="${SESSION:-$RESULTS/bench_$(date +%Y-%m-%d_%H%M%S)}"
mkdir -p "$SESSION"
ENV_FILE="$SESSION/session.env"

banner "TWIST VHigh investigation: bench session"
say "Session folder: $SESSION"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Session record and model predictions"
say "These predictions come from the model with this exact bench setup."
say "Every bench result is compared with them at the end."
"$PY" - "$CTL" <<'EOF' || { warn "no D-L2P prediction found: run model/run_campaign.py D-L2P-01 ... D-L2P-06 first"; exit 1; }
import json, subprocess, sys
p = json.loads(subprocess.run([sys.executable, sys.argv[1], 'predictions'], capture_output=True, text=True, check=True).stdout)
need = ['D-L2P-01', 'D-L2P-02', 'D-L2P-03', 'D-L2P-04', 'D-L2P-05', 'D-L2P-06']
missing = [k for k in need if k not in p]
if missing: sys.exit(f'missing {missing}')
for k, txt in zip(need, ['0.50 A, settled VHigh', '0.75 A, settled VHigh', '1.00 A, settled VHigh', '1.15 A, settled VHigh']):
    print(f'    {k}  {txt}: {p[k]["vH_end"]:.1f} V')
print(f'    D-L2P-05  1.5 A: guard stop at 80 V, {p["D-L2P-05"]["trip_t"]*1e3:.0f} ms after the step, then back to {p["D-L2P-05"]["vH_end"]:.1f} V')
print(f'    D-L2P-06  duty step 0.4 -> 0.5 at 30 V: peak iL {p["D-L2P-06"]["iL_pk"]:.2f} A')
print(f'    (campaign {p["D-L2P-01"]["campaign"]})')
EOF
ask BOARD_ID "Board serial / label on the TWIST:"
ask TWIST_HW "TWIST hardware version [1.4.3]:"; TWIST_HW="${TWIST_HW:-1.4.3}"
ask OPERATOR "Operator:"
write_env BOARD_ID "$BOARD_ID"
write_env TWIST_HW "$TWIST_HW"
write_env OPERATOR "$OPERATOR"
write_env SESSION_STARTED "$(date -Iseconds)"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Build the bench firmware"
say "Firmware: examples TWIST/DC_DC/vhigh_investigation, built with Core main"
say "in a separate worktree, so your Core checkout is untouched."
ask CORE_DIR "Core worktree [$HOME/code/Core-vhigh]:"; CORE_DIR="${CORE_DIR:-$HOME/code/Core-vhigh}"
ask EXAMPLES_DIR "examples repository [$HOME/code/examples]:"; EXAMPLES_DIR="${EXAMPLES_DIR:-$HOME/code/examples}"
if [[ ! -d "$CORE_DIR" ]]; then
  confirm "Create the worktree $CORE_DIR from ~/code/Core main?" || exit 1
  run git -C "$HOME/code/Core" worktree add "$CORE_DIR" main
fi
note "Core worktree branch: $(git -C "$CORE_DIR" branch --show-current) at $(git -C "$CORE_DIR" rev-parse --short HEAD)"
note "examples branch: $(git -C "$EXAMPLES_DIR" branch --show-current) at $(git -C "$EXAMPLES_DIR" rev-parse --short HEAD)"
[[ "$(git -C "$EXAMPLES_DIR" branch --show-current)" == "vhigh-investigation" ]] || warn "examples is not on vhigh-investigation"
EX="$EXAMPLES_DIR/TWIST/DC_DC/vhigh_investigation"
[[ -f "$EX/main.cpp" ]] || { warn "missing $EX"; exit 1; }
confirm "Copy the example into $CORE_DIR/src (replaces that worktree's src) and build?" || exit 1
run cp "$EX"/*.cpp "$EX"/*.h "$EX"/app.ini "$EX"/app.conf "$EX"/app.overlay "$CORE_DIR/src/"
(cd "$CORE_DIR" && run "$PIO" run -e USB) || { warn "build failed"; exit 1; }
write_env CORE_DIR "$CORE_DIR"
write_env EXAMPLES_DIR "$EXAMPLES_DIR"
write_env FW_CORE_COMMIT "$(git -C "$CORE_DIR" rev-parse HEAD)"
write_env FW_EXAMPLES_COMMIT "$(git -C "$EXAMPLES_DIR" rev-parse HEAD)$([[ -n "$(git -C "$EXAMPLES_DIR" status --porcelain -- TWIST/DC_DC/vhigh_investigation)" ]] && echo '-dirty')"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Flash and find the board"
warn "Every power supply OFF. Only the Spin's USB cable is connected."
step "Plug the Spin USB cable into this computer."
pause "Supplies off and USB connected? Press Enter"
if confirm "Flash the bench firmware now? (No: the board already runs it)"; then
  note "If several boards are listed, pick the TWIST under test by its serial number."
  (cd "$CORE_DIR" && run "$PIO" run -e USB -t upload) || { warn "upload failed: flash it the usual way (OwnTech upload button), then re-run"; exit 1; }
  step "Unplug the board's USB cable and plug it back in: after a flash its ports may not answer until then."
  pause "Replugged? Press Enter"
fi
say "Waiting for the board to start (1.5 s boot delay)..."
sleep 4
"$PY" "$CTL" list
FOUND="$("$PY" "$CTL" find || true)"
if [[ -n "$FOUND" ]]; then
  note "bench firmware answers on $FOUND"
else
  warn "no board answers with the bench firmware. The ThingSet port is the board's -if02 line above."
  warn "If its port hangs, the firmware is stuck: unplug and replug the board's USB and watch its console (-if00)."
fi
if [[ -n "$FOUND" ]]; then
  TS_PORT="$FOUND"   # a port that just answered wins over one saved by an earlier run
else
  ask TS_PORT "ThingSet port:"
fi
[[ -n "$TS_PORT" ]] || { warn "no port given"; exit 1; }
write_env TS_PORT "$TS_PORT"
ctl identity || { warn "no answer on $TS_PORT"; exit 1; }
trap 'printf "\n"; idle; exit 130' INT
idle

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Wiring for L2-OV-01 and L2-OV-02 (all supplies OFF)"
step "VHigh supply: set 60.0 V, current limit 1.0 A, output OFF; + on VHigh, - on GND."
step "Bleed resistor 200 ohm / 30 W or more across VHigh and GND, on a heat-safe surface."
step "Low-side supply: set 24.0 V, current limit 2.0 A, output OFF; + on LOW1, - on GND."
step "Nothing on LOW2. Leg 2 stays off in this firmware."
step "Measure the bleed resistor with a multimeter, out of circuit or with everything off."
warn "With a lab supply on VHigh, VHigh can only fall through the bleed resistor. Keep it connected."
ask R_BLEED_OHM "Measured bleed resistor (ohm):"
write_env R_BLEED_OHM "$R_BLEED_OHM"
pause "Wired as above, all outputs still OFF? Press Enter"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "MSO54 setup"
step "CH1: differential probe on VHigh to GND, 10 V/div, offset 60 V."
step "CH2: probe on LOW1 to GND, 10 V/div."
step "CH3: current probe on the wire from LOW1 to the low-side supply, arrow towards LOW1 (+ = buck), degauss, 1 A/div."
step "CH4 (optional): switch node of leg 1, high-voltage passive probe, ground on GND."
step "Horizontal 200 ms/div, acquisition Hi Res, scope in RUN."
ask IL_CHANNEL "Channel carrying the inductor current [CH3]:"; IL_CHANNEL="${IL_CHANNEL:-CH3}"
write_env IL_CHANNEL "$IL_CHANNEL"
pause "Scope set? Press Enter to test the USB link with a capture"
"$PY" "$CTL" mso-capture --session "$SESSION" --name scope_check \
  || { SKIPPED+=("MSO54 captures (scope did not answer: save screenshots by hand into $SESSION/scope/)"); warn "MSO54 did not answer: captures will be skipped"; }

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Power-up and sensor check"
step "VHigh supply output ON (60 V). The bleed draws about 0.3 A."
step "Low-side supply output ON (24 V). It should deliver almost nothing."
pause "Both supplies ON? Press Enter to read the board's sensors"
ctl settle sensor_check --seconds 1 --session "$SESSION"
say "Now read the voltages at the board terminals with a multimeter, or from the supply displays."
if ! "$PY" - "$SESSION/steps/sensor_check.json" <<'EOF'
import json, sys
m = json.load(open(sys.argv[1]))['mean']
i = m['rI1Low_A']
print(f'    I1_LOW with the PWM off: {i:+.3f} A')
sys.exit(0 if abs(i) <= 0.1 else 1)
EOF
then
  warn "I1_LOW is not about 0 A with no current flowing: the current sensor offset is not calibrated."
  warn "The current loop would act on a wrong current. Calibrate I1_LOW (OwnTech data API calibration) and re-run."
  confirm "Continue anyway (not recommended)?" || exit 1
fi
ask VHIGH_PSU_V "VHigh at the terminals (V):"
ask VLOW_PSU_V "LOW1 at the terminals (V):"
write_env VHIGH_PSU_V "$VHIGH_PSU_V"
write_env VLOW_PSU_V "$VLOW_PSU_V"
note "More than 3 % between the board's reading and the meter fails L2-OV-01.s in the record."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Guard limits and current direction (0.2 A)"
say "Bench guard: leg off, latched, if VHigh > 80 V, |I1_LOW| > 2 A or LOW1 > 30 V (every 100 us)."
ctl set Converter/wOvLimit_V 80
ctl set Converter/wILimit_A 2.0
ctl set Converter/wV1LowLimit_V 30
ctl set Converter/wClear 1
ctl set Converter/wCurrentRef_A -0.2
confirm "Start CURRENT mode at -0.2 A (power from LOW1 into VHigh)?" || { idle; exit 1; }
ctl set Converter/Mode 1
ctl settle direction_check --seconds 1.5 --session "$SESSION"
say "I1_LOW should read about -0.2 A, and the low-side supply should show it is delivering current"
say "(about 0.1 to 0.2 A). If instead LOW1 rises or the supply shows nothing, the current sign is reversed."
if ! confirm "Low-side supply delivering current, and I1_LOW about -0.2 A?"; then
  idle; warn "Direction check failed: stopped. Check the I1_LOW sign before going on."; exit 1
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "L2-OV-01: current steps into VHigh"
say "Four steps of the reference. At each one VHigh settles where the bleed burns what is injected."
say "Expected: 60 V at 0.5 and 0.75 A, then about 69 V at 1.0 A and 74 V at 1.15 A."
confirm "Run the four steps (about 15 s in total)?" || { idle; exit 1; }
for I in 0.50 0.75 1.00 1.15; do
  ctl set Converter/wCurrentRef_A "-$I" >/dev/null
  printf '  %s%s A:%s ' "$BOLD" "$I" "$RESET"
  ctl settle "ov01_${I}A" --seconds 2.5 --session "$SESSION"
  if ctl read | grep -q '"rTripped": true'; then warn "guard tripped at $I A: see Converter/rTripReason"; break; fi
done
"$PY" "$CTL" mso-capture --session "$SESSION" --name ov01_1.15A || true
ctl set Converter/wCurrentRef_A 0 >/dev/null
sleep 1
idle
say "VHigh above 60 V at 1.0 A is F-1 on the board: the supply cannot take the power back."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "L2-OV-02: the guard stops the leg at 80 V"
say "1.5 A would settle VHigh at about 85 V. The guard must open the leg at 80 V,"
say "then the bleed brings VHigh back to 60 V."
step "MSO54: trigger CH1 rising edge at 76 V, normal mode, single sequence; horizontal 200 ms/div."
pause "Scope set? Press Enter"
ctl set Converter/wClear 1 >/dev/null
ctl set Converter/wCurrentRef_A -1.0 >/dev/null
confirm "Start at 1.0 A, then step to 1.5 A until the guard stops the leg?" || { idle; exit 1; }
ctl set Converter/Mode 1 >/dev/null
sleep 2
ctl fwscope-arm
"$PY" "$CTL" mso-arm || true
ctl set Converter/wCurrentRef_A -1.5 >/dev/null
ctl wait-trip --timeout 5 --session "$SESSION" --name ov02_trip || { idle; warn "no trip within 5 s: stopped by hand"; }
ctl settle ov02_after --seconds 2 --session "$SESSION"
ctl fwscope-read --session "$SESSION" --name ov02 || warn "firmware scope not read"
"$PY" "$CTL" mso-capture --session "$SESSION" --name ov02 || true
ctl set Converter/wCurrentRef_A 0 >/dev/null
ctl set Converter/wClear 1 >/dev/null
idle

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Rewire for L2-STP-01 (all supplies OFF)"
step "Both supply outputs OFF."
ctl settle discharge --seconds 2 --session "$SESSION" || true
step "Wait until VHigh and LOW1 read below 5 V on a meter. LOW1 has no bleed: discharge it through a 10 ohm resistor if needed."
step "Disconnect the low-side supply from LOW1."
step "Connect a 10 ohm / 50 W or more load across LOW1 and GND."
step "Set the VHigh supply to 30.0 V, current limit 2.0 A, output still OFF. Keep the bleed resistor."
step "MSO54: CH3 1 A/div, trigger CH3 rising at 3.5 A, single sequence; horizontal 200 us/div; CH1 5 V/div, offset 30 V."
ask R_LOAD_OHM "Measured LOW1 load resistor (ohm):"
write_env R_LOAD_OHM "$R_LOAD_OHM"
pause "Rewired, outputs OFF? Press Enter"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "L2-STP-01: duty step 0.4 to 0.5 at 30 V"
step "VHigh supply output ON (30 V)."
pause "On? Press Enter"
ctl set Converter/wOvLimit_V 40 >/dev/null
ctl set Converter/wILimit_A 6.5 >/dev/null
ctl set Converter/wV1LowLimit_V 20 >/dev/null
ctl set Converter/wDuty0 0.4 >/dev/null
ctl set Converter/wDuty1 0.5 >/dev/null
ctl set Converter/wStep 0 >/dev/null
ctl set Converter/wClear 1 >/dev/null
confirm "Start STEP mode at duty 0.4 (LOW1 about 12 V into 10 ohm)?" || { idle; exit 1; }
ctl set Converter/Mode 2 >/dev/null
ctl settle stp_before --seconds 1.5 --session "$SESSION"
"$PY" "$CTL" mso-arm || true
confirm "Step the duty to 0.5 (expected peak about 5.2 A)?" || { idle; exit 1; }
ctl set Converter/wStep 1 >/dev/null
sleep 1
"$PY" "$CTL" mso-capture --session "$SESSION" --name stp01 || warn "save the MSO54 screen by hand into $SESSION/scope/stp01/"
ctl settle stp_after --seconds 1 --session "$SESSION"
ctl set Converter/wStep 0 >/dev/null
idle

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Power down and record"
step "VHigh supply output OFF. Leave everything wired until VHigh reads below 5 V."
pause "Supplies off? Press Enter to write the record"
ask NOTES "Anything observed worth keeping (smell, noise, heating, a surprise)? Press Enter for none:"
write_env NOTES "${NOTES:-none}"
write_env SESSION_ENDED "$(date -Iseconds)"
"$PY" "$CTL" record --session "$SESSION"
open_url "file://$RESULTS/control-center.html#bench"
say "Session record: $SESSION/report.html"

finish
}

run_wizard "$@"; exit
